/* =====================================================================
   НАСТРОЙКИ — меняй значения здесь
   ===================================================================== */
:root {
  /* затемнение фоновой картинки: 0 = без затемнения, 1 = чёрный экран */
  --fw-dim: 0.2;
  /* Дополнительное затемнение под чатом, списком тем форума и списком друзей. */
  --fw-chat-dim: 0.32;
  /* затемнение боковых панелей (серверы, каналы, участники) */
  --fw-panel-dim: 0.56;

  /* размер текста на кнопках в звонках и стримах («Смотреть стрим» и т.п.) */
  --fw-call-button-font: 12px;

  /* скругления: 0px — квадратно, как в Minecraft; 8px — как в обычном Discord */
  --fw-radius: 2px;

  /* тень у текста, как в Minecraft. Поставь none, чтобы убрать */
  --fw-text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.85);

  /* затемнение краёв экрана (виньетка): 0 = нет */
  --fw-vignette: 0.25;

    /* Лесная иллюстрация, кадры текста на мониторе и статичный кадр. */
  --fw-bg: url("data:image/webp;base64,");
  --fw-monitor-animation: url("data:image/webp;base64,");
  --fw-monitor-still: url("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEgAAAAnCAYAAACsTw7IAAAACXBIWXMAAAsTAAALEwEAmpwYAAAAb0lEQVRoge3YOwrAIBAFQO+dW22T4yWks4rFJrDqDAgWW8gTv63BJ+I8rqe99XeuLzegKFbPSLUZi2L15QYUxeoBAAAA2Ezmw6m37IeTgMjJLKVYdVn1BESO02pAQOTYpAcExJxPjZjlwikgaD+4AU0hqWOPBGhMAAAAAElFTkSuQmCC");

  /* палитра лесной иллюстрации */
  --fw-bone: #f2ecd6;        /* основной текст — как светлая грань клинка */
  --fw-bone-dim: #bbc4a9;    /* второстепенный текст */
  --fw-ash: #9da990;         /* приглушённый текст */
  --fw-moss: #7d9a53;        /* мох — акцентный цвет */
  --fw-moss-hi: #bfdb89;
  --fw-btn: #43582b;         /* кнопки (контраст текста 5.8:1) */
  --fw-btn-hover: #506738;
  --fw-btn-active: #354722;
  --fw-btn-rim: #768e4e;
  --fw-lichen: #bfdb89;      /* лишайник — ссылки, выделение */
  --fw-root: #6b5240;        /* корни — тёплый акцент */
  --fw-void: #151d12;        /* фон всплывающих окон */
  --fw-line: #aebf7930;

  --fw-font: "JetBrains Mono", "Consolas", monospace;
}

/* =====================================================================
   ШРИФТ — JetBrains Mono (SIL Open Font License 1.1)
   ===================================================================== */
@font-face {
  font-family: "JetBrains Mono";
  src: url("data:font/woff2;base64,") format("woff2");
  font-style: normal;
  font-weight: 100 800;
  font-display: swap;
}

@font-face {
  font-family: "JetBrains Mono";
  src: url("data:font/woff2;base64,") format("woff2");
  font-style: italic;
  font-weight: 100 800;
  font-display: swap;
}

