/* =====================================================================
   ФОН
   ===================================================================== */
html, body {
  background: #000 !important;
}

#app-mount {
  background:
    radial-gradient(ellipse 85% 95% at 66% 42%, transparent 45%, rgba(0, 0, 0, var(--fw-vignette)) 100%),
    linear-gradient(rgba(0, 0, 0, var(--fw-dim)), rgba(0, 0, 0, var(--fw-dim))),
    var(--fw-bg) center / cover no-repeat fixed,
    #000 !important;
  isolation: isolate;
}

/* Экран монитора расположен относительно изображения с background-size: cover. */
#app-mount::after {
  --fw-scene-pixel: max(calc(100vw / 1672), calc(100vh / 941));
  content: "";
  position: fixed;
  left: calc(50vw + -306 * var(--fw-scene-pixel));
  top: calc(50vh + 0.5 * var(--fw-scene-pixel));
  width: calc(72 * var(--fw-scene-pixel));
  height: calc(39 * var(--fw-scene-pixel));
  background: var(--fw-monitor-animation) center / 100% 100% no-repeat;
  transform: translateZ(0);
  z-index: -1;
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  #app-mount::after {
    background-image: var(--fw-monitor-still);
    transform: none;
  }
}

/* Фоновый слой Discord прозрачен, чтобы была видна иллюстрация. */
#app-mount [class^="bg_"],
#app-mount [class*=" bg_"] {
  background: transparent !important;
}

/* =====================================================================
   ПАНЕЛИ — затемнение, чтобы читалось поверх меча
   ===================================================================== */
/* список серверов */
#app-mount [class*="guilds_"] {
  background: rgba(0, 0, 0, calc(var(--fw-panel-dim) + 0.1)) !important;
}
/* список каналов / личных сообщений */
#app-mount [class*="sidebarList_"] {
  background: rgba(0, 0, 0, var(--fw-panel-dim)) !important;
}
/* панель пользователя внизу слева */
#app-mount [class*="panels_"] {
  background: rgba(8, 8, 7, 0.8) !important;
  border-top: 1px solid var(--fw-line);
}
/* верхняя полоса окна. Не трогаем другие компоненты с именем bar_. */
#app-mount :is([class^="titleBar_"], [class*=" titleBar_"]) {
  background: rgba(0, 0, 0, 0.45) !important;
  border-bottom: 1px solid var(--fw-line) !important;
}
/* Чат, форумные каналы и список друзей: затемнение усиливается книзу. */
#app-mount [class*="chatContent_"],
#app-mount .container_BkGrJJ[data-member-list-open],
#app-mount [class*="peopleColumn_"] {
  background: linear-gradient(
    to bottom,
    rgba(0, 0, 0, calc(var(--fw-chat-dim) * 0.7)),
    rgba(0, 0, 0, calc(var(--fw-chat-dim) * 1.7))
  ) !important;
}
/* «Активные контакты» и список участников — плотнее */
#app-mount [class*="nowPlayingColumn_"] {
  background: rgba(6, 6, 5, 0.78) !important;
  border-left: 1px solid var(--fw-line) !important;
}
#app-mount [class*="membersWrap_"] {
  background: rgba(0, 0, 0, calc(var(--fw-panel-dim) + 0.15)) !important;
}
/* заголовок канала */
#app-mount section[class*="title_"] {
  background: rgba(0, 0, 0, 0.35) !important;
  border-bottom: 1px solid var(--fw-line) !important;
  box-shadow: none !important;
}

/* список друзей: почти невидимые разделители, подсветка строки при наведении */
#app-mount [class*="peopleListItem_"] {
  border-color: rgba(221, 216, 204, 0.035) !important;
}
#app-mount [class*="peopleListItem_"]:hover {
  background: rgba(174, 189, 170, 0.07) !important;
}
/* круглые кнопки 💬 ⋮ — свой тёмный фон, чтобы не терялись на камне */
#app-mount [class*="peopleListItem_"] [class*="actionButton_"] {
  background: rgba(14, 14, 12, 0.85) !important;
  border: 1px solid var(--fw-line) !important;
  color: var(--fw-bone) !important;
}
#app-mount [class*="peopleListItem_"] [class*="actionButton_"]:hover {
  background: var(--fw-btn) !important;
  border-color: var(--fw-btn-rim) !important;
}

/* =====================================================================
   ТЕКСТ — шрифт, тень, без лигатур
   ===================================================================== */
body,
#app-mount {
  font-family: var(--fw-font) !important;
  text-shadow: var(--fw-text-shadow);
  font-variant-ligatures: none;
  font-feature-settings: "liga" 0, "calt" 0;
}
input, textarea, button, select,
[contenteditable="true"], [role="textbox"] {
  font-family: var(--fw-font) !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "liga" 0, "calt" 0 !important;
}
code, pre, .hljs, [class*="codeBlock"], [class*="inlineCode"] {
  font-family: var(--fw-font) !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "liga" 0, "calt" 0 !important;
}

/* Размер текста на кнопках звонков и стримов. */
#app-mount [class*="callContainer_"] button,
#app-mount [class*="callContainer_"] button *,
#app-mount [class*="videoControls_"] button,
#app-mount [class*="videoControls_"] button *,
#app-mount [class*="callContainer_"] [class*="tile_"] button,
#app-mount [class*="callContainer_"] [class*="tile_"] button *,
#app-mount [class*="streamPreview"] button,
#app-mount [class*="streamPreview"] button * {
  font-size: var(--fw-call-button-font) !important;
  letter-spacing: -0.02em !important;
  line-height: 1.25 !important;
}
#app-mount [class*="callContainer_"] button,
#app-mount [class*="callContainer_"] [class*="tile_"] button,
#app-mount [class*="streamPreview"] button {
  min-height: 0 !important;
  max-width: 100%;
}
/* во всех остальных кнопках — чуть плотнее буквы, чтобы надписи не вылезали */
#app-mount button {
  letter-spacing: -0.02em;
}

/* блоки кода */
[class*="markup_"] code,
[class*="markup_"] pre code {
  background: rgba(0, 0, 0, 0.55) !important;
  border: 1px solid var(--fw-line) !important;
}

/* цитаты — полоска цвета мха */
[class*="blockquoteDivider_"] {
  background: var(--fw-moss) !important;
}

/* выделение текста */
::selection {
  background: rgba(125, 122, 69, 0.55);
  color: #f0ece2;
}

/* =====================================================================
   ВСПЛЫВАЮЩИЕ ОКНА — рамка, как у гравюры
   ===================================================================== */
/* Только известные плавающие компоненты Discord.
   Обобщённый [role="dialog"] > [class^="root_"] затрагивал и чужие диалоги. */
#app-mount :is(
  [class^="menu_"], [class*=" menu_"],
  [class^="tooltip_"][class*="tooltipPrimary"], [class*=" tooltip_"][class*="tooltipPrimary"],
  [class^="userPopout_"], [class*=" userPopout_"],
  [class^="userProfileOuter_"], [class*=" userProfileOuter_"],
  [class^="autocomplete_"], [class*=" autocomplete_"]
) {
  border: 1px solid rgba(221, 216, 204, 0.14) !important;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.8) !important;
}

/* затемнение за модалкой */
[class^="backdrop_"], [class*=" backdrop_"] {
  background: rgba(0, 0, 0, 0.82) !important;
}

/* =====================================================================
   МЕЛОЧИ
   ===================================================================== */
/* кнопка Discord (личные сообщения) над списком серверов */
#app-mount [data-list-item-id="guildsnav___home"] [class*="childWrapper_"] {
  background-color: rgba(28, 28, 25, 0.9) !important;
  color: var(--fw-bone) !important;
}
#app-mount [data-list-item-id="guildsnav___home"]:hover [class*="childWrapper_"],
#app-mount [data-list-item-id="guildsnav___home"][class*="selected_"] [class*="childWrapper_"],
#app-mount [class*="selected_"] > [data-list-item-id="guildsnav___home"] [class*="childWrapper_"] {
  background-color: var(--fw-btn) !important;
  color: #f0ece2 !important;
}

/* «Добавить в друзья» */
#app-mount [class*="addFriend_"] {
  background-color: var(--fw-btn) !important;
  color: #f0ece2 !important;
  border: 1px solid var(--fw-btn-rim) !important;
}
#app-mount [class*="addFriend_"]:hover {
  background-color: var(--fw-btn-hover) !important;
}
#app-mount [class*="addFriend_"][aria-selected="true"] {
  background-color: transparent !important;
  color: var(--fw-moss-hi) !important;
}

/* полоска у выбранного сервера — цвета мха */
[class^="pill_"] [class^="item_"], [class*=" pill_"] [class^="item_"] {
  background: var(--fw-moss-hi) !important;
}

/* тонкие скроллбары */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb {
  background: rgba(174, 189, 170, 0.22);
  border-radius: 0;
}
::-webkit-scrollbar-thumb:hover { background: rgba(174, 189, 170, 0.35); }
::-webkit-scrollbar-track { background: transparent; }

